// Offline readers for Terraform / OpenTofu artifacts: terraform.tfstate (v4)
// files and the JSON plan representation printed by `terraform show -json
// <planfile>` (or `tofu show -json`). No credentials and no network.
//
// Sensitive values never leave the worker: state attributes listed in an
// instance's sensitive_attributes, plan values marked in before_sensitive /
// after_sensitive, and sensitive outputs are replaced by "(sensitive value)"
// (attributes) or NULL (output values).
//
// A path starting with "sample:" reads one of the documents bundled with the
// worker (generated by scripts/gen-terraform-fixtures.sh with OpenTofu and the
// null/random/local providers), so every example runs straight after ATTACH.

package terraform

import (
	"context"
	"embed"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"reflect"
	"sort"
	"strconv"
	"strings"

	"github.com/Query-farm/vgi-go/vgi"
	"github.com/Query-farm/vgi-rpc-go/vgirpc"
	"github.com/apache/arrow-go/v18/arrow"
)

//go:embed samples/*
var samples embed.FS

// samplePrefix selects a bundled document.
const samplePrefix = "sample:"

// maskedText replaces a sensitive attribute value.
const maskedText = "(sensitive value)"

// maxDocumentBytes bounds one state / plan document.
const maxDocumentBytes = 1 << 30

// fileBatchRows is the number of rows per emitted batch.
const fileBatchRows = 5000

// readDocument reads a local file or a bundled sample.
func readDocument(path string) ([]byte, error) {
	if name, ok := strings.CutPrefix(path, samplePrefix); ok {
		b, err := samples.ReadFile("samples/" + strings.TrimLeft(name, "/"))
		if err != nil {
			return nil, fmt.Errorf("no bundled sample %q (available: %s)", name, strings.Join(sampleNames(), ", "))
		}
		return b, nil
	}
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer func() { _ = f.Close() }()
	b, err := io.ReadAll(io.LimitReader(f, maxDocumentBytes+1))
	if err != nil {
		return nil, err
	}
	if len(b) > maxDocumentBytes {
		return nil, fmt.Errorf("%s is larger than %d bytes", path, maxDocumentBytes)
	}
	return b, nil
}

func sampleNames() []string {
	entries, _ := samples.ReadDir("samples")
	out := make([]string, 0, len(entries))
	for _, e := range entries {
		out = append(out, samplePrefix+e.Name())
	}
	return out
}

// decodeJSON decodes a document keeping numbers exact.
func decodeJSON(b []byte, v any) error {
	dec := json.NewDecoder(strings.NewReader(string(b)))
	dec.UseNumber()
	return dec.Decode(v)
}

// toJSON encodes a decoded value for a JSON column (nil stays NULL).
func toJSON(v any) any {
	if v == nil {
		return nil
	}
	b, err := json.Marshal(v)
	if err != nil {
		return nil
	}
	return jsonText(b)
}

func strOrNil(v any) any {
	if s, ok := v.(string); ok && s != "" {
		return s
	}
	return nil
}

func listOfStrings(v []string) []any {
	out := make([]any, len(v))
	for i, s := range v {
		out[i] = s
	}
	return out
}

// indexKey renders a count / for_each key: 0 -> "0", "a" -> "a".
func indexKey(v any) any {
	switch x := v.(type) {
	case nil:
		return nil
	case string:
		return x
	case json.Number:
		return x.String()
	}
	return fmt.Sprint(v)
}

// instanceAddress builds module.x.type.name[key].
func instanceAddress(module, mode, typ, name string, key any) string {
	var b strings.Builder
	if module != "" {
		b.WriteString(module + ".")
	}
	if mode == "data" {
		b.WriteString("data.")
	}
	b.WriteString(typ + "." + name)
	switch x := key.(type) {
	case json.Number:
		b.WriteString("[" + x.String() + "]")
	case string:
		b.WriteString("[" + strconv.Quote(x) + "]")
	}
	return b.String()
}

// pathString renders a path of steps as a.b[0]["k"].
func pathString(steps []any) string {
	var b strings.Builder
	for i, s := range steps {
		switch x := s.(type) {
		case string:
			if i > 0 {
				b.WriteString(".")
			}
			b.WriteString(x)
		case json.Number:
			b.WriteString("[" + x.String() + "]")
		default:
			fmt.Fprintf(&b, "[%v]", x)
		}
	}
	return b.String()
}

// ---- sensitive masking -----------------------------------------------------

// maskMirror replaces every leaf of v that a sensitivity mirror marks true
// (plan before_sensitive / after_sensitive shape).
func maskMirror(v, mirror any) any {
	switch m := mirror.(type) {
	case bool:
		if m && v != nil {
			return maskedText
		}
		return v
	case map[string]any:
		obj, ok := v.(map[string]any)
		if !ok {
			return v
		}
		out := make(map[string]any, len(obj))
		for k, val := range obj {
			if sub, ok := m[k]; ok {
				out[k] = maskMirror(val, sub)
			} else {
				out[k] = val
			}
		}
		return out
	case []any:
		arr, ok := v.([]any)
		if !ok {
			return v
		}
		out := make([]any, len(arr))
		for i, val := range arr {
			if i < len(m) {
				out[i] = maskMirror(val, m[i])
			} else {
				out[i] = val
			}
		}
		return out
	}
	return v
}

// stateStep is one step of a state sensitive_attributes path.
type stateStep struct {
	Type  string `json:"type"`
	Value any    `json:"value"`
}

// stepKey turns a step into a map key (string) or list index (json.Number).
func stepKey(s stateStep) any {
	if s.Type == "get_attr" {
		return s.Value
	}
	if m, ok := s.Value.(map[string]any); ok {
		return m["value"]
	}
	return s.Value
}

// maskPath replaces the value at path inside v (in place where possible).
func maskPath(v any, path []any) any {
	if len(path) == 0 {
		if v == nil {
			return nil
		}
		return maskedText
	}
	switch x := v.(type) {
	case map[string]any:
		k := fmt.Sprint(path[0])
		if n, ok := path[0].(json.Number); ok {
			k = n.String()
		}
		if sub, ok := x[k]; ok {
			x[k] = maskPath(sub, path[1:])
		}
		return x
	case []any:
		n, ok := path[0].(json.Number)
		if !ok {
			return x
		}
		i, err := strconv.Atoi(n.String())
		if err == nil && i >= 0 && i < len(x) {
			x[i] = maskPath(x[i], path[1:])
		}
		return x
	}
	return v
}

// ---- the file table framework ---------------------------------------------

// FileState is the resumable cursor of a file reader: the next row offset.
type FileState struct {
	Offset int
	Done   bool
}

type pathArgs struct {
	Path string `vgi:"name=path,pos=0,doc=Path of the document on the worker's filesystem, or sample:<name> for a bundled sample (sample:basic.tfstate, sample:change.plan.json)."`
}

// fileDef defines one offline reader.
type fileDef struct {
	Name       string
	Docs       fnDocs
	Executable []map[string]any
	Schema     *arrow.Schema
	Rows       func(b []byte) ([][]any, error)
}

type fileFunc struct{ def *fileDef }

var _ vgi.TypedTableFunc[FileState] = (*fileFunc)(nil)

func (f *fileFunc) Name() string { return f.def.Name }

func (f *fileFunc) Metadata() vgi.FunctionMetadata {
	d := f.def.Docs
	tags := objectTags(d)
	tags["vgi.result_columns_schema"] = mustJSON(schemaColumns(f.def.Schema))
	if len(f.def.Executable) > 0 {
		tags["vgi.executable_examples"] = mustJSON(f.def.Executable)
	}
	return vgi.FunctionMetadata{
		Description:        d.Description,
		Stability:          vgi.StabilityVolatile,
		ProjectionPushdown: true,
		Tags:               tags,
		Examples:           d.Examples,
	}
}

func (f *fileFunc) ArgumentSpecs() []vgi.ArgSpec { return vgi.DeriveArgSpecs(pathArgs{}) }

func (f *fileFunc) OnBind(*vgi.BindParams) (*vgi.BindResponse, error) {
	return vgi.BindSchema(f.def.Schema)
}

func (f *fileFunc) NewState(*vgi.ProcessParams) (*FileState, error) { return &FileState{}, nil }

func (f *fileFunc) Process(_ context.Context, p *vgi.ProcessParams, st *FileState, out *vgirpc.OutputCollector) error {
	if st.Done {
		return out.Finish()
	}
	var a pathArgs
	if err := vgi.BindArgs(p.Args, &a); err != nil {
		return err
	}
	if strings.TrimSpace(a.Path) == "" {
		return errEmptyArg("path")
	}
	b, err := readDocument(a.Path)
	if err != nil {
		return fmt.Errorf("%s: %w", f.def.Name, err)
	}
	rows, err := f.def.Rows(b)
	if err != nil {
		return fmt.Errorf("%s(%q): %w", f.def.Name, a.Path, err)
	}
	if st.Offset >= len(rows) {
		st.Done = true
		return out.Finish()
	}
	end := min(st.Offset+fileBatchRows, len(rows))
	batch, err := buildBatch(p.OutputSchema, f.def.Schema, rows[st.Offset:end])
	if err != nil {
		return err
	}
	st.Offset = end
	if end >= len(rows) {
		st.Done = true
	}
	return out.Emit(batch)
}

func newFileTable(def *fileDef) vgi.TableFunction {
	return vgi.AsTableFunction[FileState](&fileFunc{def: def})
}

// ---- terraform.tfstate -----------------------------------------------------

type stateFile struct {
	Version          json.Number `json:"version"`
	TerraformVersion string      `json:"terraform_version"`
	Serial           json.Number `json:"serial"`
	Lineage          string      `json:"lineage"`
	Outputs          map[string]struct {
		Value     any  `json:"value"`
		Type      any  `json:"type"`
		Sensitive bool `json:"sensitive"`
	} `json:"outputs"`
	Resources []struct {
		Module    string `json:"module"`
		Mode      string `json:"mode"`
		Type      string `json:"type"`
		Name      string `json:"name"`
		Provider  string `json:"provider"`
		Instances []struct {
			IndexKey            any               `json:"index_key"`
			SchemaVersion       json.Number       `json:"schema_version"`
			Status              string            `json:"status"`
			Deposed             string            `json:"deposed"`
			Attributes          any               `json:"attributes"`
			AttributesFlat      any               `json:"attributes_flat"`
			SensitiveAttributes []json.RawMessage `json:"sensitive_attributes"`
			Dependencies        []string          `json:"dependencies"`
			CreateBeforeDestroy bool              `json:"create_before_destroy"`
		} `json:"instances"`
	} `json:"resources"`
}

func parseState(b []byte) (*stateFile, error) {
	var s stateFile
	if err := decodeJSON(b, &s); err != nil {
		return nil, fmt.Errorf("not a JSON state file: %w", err)
	}
	if s.Version.String() != "4" {
		if s.Version == "" {
			return nil, errors.New("not a Terraform state file (no \"version\" field)")
		}
		return nil, fmt.Errorf("unsupported state format version %s (only version 4, written by Terraform 0.12+ and OpenTofu, is read)", s.Version)
	}
	return &s, nil
}

// sensitivePaths decodes sensitive_attributes entries into key paths.
func sensitivePaths(raw []json.RawMessage) [][]any {
	var out [][]any
	for _, r := range raw {
		var steps []stateStep
		if decodeJSON(r, &steps) != nil {
			continue
		}
		path := make([]any, 0, len(steps))
		for _, s := range steps {
			path = append(path, stepKey(s))
		}
		if len(path) > 0 {
			out = append(out, path)
		}
	}
	return out
}

func numOrNil(n json.Number) any {
	if v, err := n.Int64(); err == nil {
		return v
	}
	return nil
}

var stateSchema = arrow.NewSchema([]arrow.Field{
	column("address", tString, "Instance address, e.g. module.naming.random_id.suffix or random_integer.port[0].", false),
	column("module_address", tString, "Module path (module.a.module.b); NULL for the root module.", true),
	column("mode", tString, "managed (a resource) or data (a data source).", false),
	column("type", tString, "Resource type, e.g. aws_instance.", false),
	column("name", tString, "Resource name in the configuration.", false),
	column("instance_index", tString, "count index or for_each key as text; NULL for a single instance.", true),
	column("provider", tString, "Provider configuration address, e.g. provider[\"registry.terraform.io/hashicorp/aws\"].", true),
	column("schema_version", tInt64, "Provider schema version of the attributes.", true),
	column("attributes", tJSON, "Instance attributes as JSON, with every sensitive attribute replaced by \"(sensitive value)\".", true),
	column("sensitive_attributes", tStrList, "Paths of the attributes masked as sensitive, e.g. result or tags[\"secret\"].", true),
	column("dependencies", tStrList, "Addresses this instance depends on.", true),
	column("tainted", tBool, "Whether the instance is tainted (will be replaced on the next apply).", false),
	column("deposed", tString, "Deposed object key (a create_before_destroy leftover); NULL for the current object.", true),
	column("create_before_destroy", tBool, "Whether the instance is replaced create-before-destroy.", false),
	column("terraform_version", tString, "Terraform / OpenTofu version that wrote the state.", true),
	column("serial", tInt64, "State serial number.", true),
	column("lineage", tString, "State lineage id (shared by every serial of one state).", true),
}, nil)

func stateRows(b []byte) ([][]any, error) {
	s, err := parseState(b)
	if err != nil {
		return nil, err
	}
	var rows [][]any
	for _, r := range s.Resources {
		mode := r.Mode
		if mode == "" {
			mode = "managed"
		}
		for _, in := range r.Instances {
			attrs := in.Attributes
			if attrs == nil {
				attrs = in.AttributesFlat
			}
			paths := sensitivePaths(in.SensitiveAttributes)
			names := make([]string, 0, len(paths))
			for _, p := range paths {
				attrs = maskPath(attrs, p)
				names = append(names, pathString(p))
			}
			deps := in.Dependencies
			if deps == nil {
				deps = []string{}
			}
			rows = append(rows, []any{
				instanceAddress(r.Module, mode, r.Type, r.Name, in.IndexKey), strOrNil(r.Module), mode, r.Type, r.Name,
				indexKey(in.IndexKey), strOrNil(r.Provider), numOrNil(in.SchemaVersion), toJSON(attrs),
				listOfStrings(names), listOfStrings(deps), in.Status == "tainted", strOrNil(in.Deposed),
				in.CreateBeforeDestroy, strOrNil(s.TerraformVersion), numOrNil(s.Serial), strOrNil(s.Lineage),
			})
		}
	}
	return rows, nil
}

var stateOutputsSchema = arrow.NewSchema([]arrow.Field{
	column("name", tString, "Output name.", false),
	column("sensitive", tBool, "Whether the output is marked sensitive.", false),
	column("value", tJSON, "Output value as JSON; NULL when sensitive.", true),
	column("type", tJSON, "Terraform type of the value as JSON, e.g. \"string\" or [\"tuple\",[\"number\",\"number\"]].", true),
}, nil)

func stateOutputRows(b []byte) ([][]any, error) {
	s, err := parseState(b)
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(s.Outputs))
	for n := range s.Outputs {
		names = append(names, n)
	}
	sort.Strings(names)
	rows := make([][]any, 0, len(names))
	for _, n := range names {
		o := s.Outputs[n]
		var v any
		if !o.Sensitive {
			v = toJSON(o.Value)
		}
		rows = append(rows, []any{n, o.Sensitive, v, toJSON(o.Type)})
	}
	return rows, nil
}

// ---- terraform show -json plan ---------------------------------------------

type planChange struct {
	Actions         []string `json:"actions"`
	Before          any      `json:"before"`
	After           any      `json:"after"`
	AfterUnknown    any      `json:"after_unknown"`
	BeforeSensitive any      `json:"before_sensitive"`
	AfterSensitive  any      `json:"after_sensitive"`
	ReplacePaths    [][]any  `json:"replace_paths"`
}

type planFile struct {
	FormatVersion    string `json:"format_version"`
	TerraformVersion string `json:"terraform_version"`
	ResourceChanges  []struct {
		Address         string     `json:"address"`
		PreviousAddress string     `json:"previous_address"`
		ModuleAddress   string     `json:"module_address"`
		Mode            string     `json:"mode"`
		Type            string     `json:"type"`
		Name            string     `json:"name"`
		Index           any        `json:"index"`
		ProviderName    string     `json:"provider_name"`
		Deposed         string     `json:"deposed"`
		ActionReason    string     `json:"action_reason"`
		Change          planChange `json:"change"`
	} `json:"resource_changes"`
	OutputChanges map[string]planChange `json:"output_changes"`
}

func parsePlan(b []byte) (*planFile, error) {
	var p planFile
	if err := decodeJSON(b, &p); err != nil {
		return nil, fmt.Errorf("not a JSON plan (the output of `terraform show -json <planfile>`): %w", err)
	}
	if p.FormatVersion == "" {
		return nil, errors.New("not a JSON plan: no format_version (produce it with `terraform show -json <planfile>` or `tofu show -json <planfile>`)")
	}
	return &p, nil
}

// actionSummary condenses an actions list into one verb.
func actionSummary(actions []string) string {
	switch {
	case len(actions) == 2:
		return "replace"
	case len(actions) == 1:
		return actions[0]
	}
	return strings.Join(actions, ",")
}

// changedAttributes lists the top-level attributes that differ between before
// and after, or whose new value is unknown until apply.
func changedAttributes(c planChange) []string {
	before, _ := c.Before.(map[string]any)
	after, _ := c.After.(map[string]any)
	unknown, _ := c.AfterUnknown.(map[string]any)
	set := map[string]bool{}
	for k, bv := range before {
		if av, ok := after[k]; !ok || !reflect.DeepEqual(av, bv) {
			set[k] = true
		}
	}
	for k, av := range after {
		if bv, ok := before[k]; !ok || !reflect.DeepEqual(av, bv) {
			set[k] = true
		}
	}
	for k, u := range unknown {
		if hasTrue(u) {
			set[k] = true
		}
	}
	out := make([]string, 0, len(set))
	for k := range set {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// hasTrue reports whether an after_unknown mirror marks anything unknown.
func hasTrue(v any) bool {
	switch x := v.(type) {
	case bool:
		return x
	case map[string]any:
		for _, e := range x {
			if hasTrue(e) {
				return true
			}
		}
	case []any:
		for _, e := range x {
			if hasTrue(e) {
				return true
			}
		}
	}
	return false
}

var planSchema = arrow.NewSchema([]arrow.Field{
	column("address", tString, "Instance address, e.g. random_pet.server or module.naming.random_id.suffix.", false),
	column("module_address", tString, "Module path; NULL for the root module.", true),
	column("mode", tString, "managed or data.", false),
	column("type", tString, "Resource type.", false),
	column("name", tString, "Resource name.", false),
	column("instance_index", tString, "count index or for_each key as text; NULL for a single instance.", true),
	column("provider_name", tString, "Provider source address, e.g. registry.terraform.io/hashicorp/aws.", true),
	column("action", tString, "One verb: create, update, delete, replace, read or no-op (replace = delete+create in either order).", false),
	column("actions", tStrList, "The raw action list, e.g. [delete, create] (destroy-before-create) or [create, delete].", false),
	column("action_reason", tString, "Why the action was chosen, e.g. replace_because_cannot_update, replace_because_tainted, delete_because_no_resource_config.", true),
	column("replace_paths", tStrList, "Attribute paths that force the replacement, e.g. keepers or tags[\"Name\"].", true),
	column("changed_attributes", tStrList, "Top-level attributes whose value changes or becomes unknown until apply.", false),
	column("previous_address", tString, "Address before a moved block renamed it.", true),
	column("deposed", tString, "Deposed object key the change applies to; NULL for the current object.", true),
	column("before", tJSON, "Attributes before the change (sensitive values masked); NULL on create.", true),
	column("after", tJSON, "Attributes after the change (sensitive values masked; unknown values are absent, see after_unknown); NULL on delete.", true),
	column("after_unknown", tJSON, "Mirror of after marking values known only after apply with true.", true),
	column("terraform_version", tString, "Terraform / OpenTofu version that produced the plan.", true),
}, nil)

func planRows(b []byte) ([][]any, error) {
	p, err := parsePlan(b)
	if err != nil {
		return nil, err
	}
	rows := make([][]any, 0, len(p.ResourceChanges))
	for _, rc := range p.ResourceChanges {
		c := rc.Change
		var replace []any
		if len(c.ReplacePaths) > 0 {
			replace = make([]any, 0, len(c.ReplacePaths))
			for _, path := range c.ReplacePaths {
				replace = append(replace, pathString(path))
			}
		}
		mode := rc.Mode
		if mode == "" {
			mode = "managed"
		}
		var replaceCol any
		if replace != nil {
			replaceCol = replace
		}
		rows = append(rows, []any{
			rc.Address, strOrNil(rc.ModuleAddress), mode, rc.Type, rc.Name, indexKey(rc.Index), strOrNil(rc.ProviderName),
			actionSummary(c.Actions), listOfStrings(c.Actions), strOrNil(rc.ActionReason), replaceCol,
			listOfStrings(changedAttributes(c)), strOrNil(rc.PreviousAddress), strOrNil(rc.Deposed),
			toJSON(maskMirror(c.Before, c.BeforeSensitive)), toJSON(maskMirror(c.After, c.AfterSensitive)),
			toJSON(c.AfterUnknown), strOrNil(p.TerraformVersion),
		})
	}
	return rows, nil
}

var planOutputsSchema = arrow.NewSchema([]arrow.Field{
	column("name", tString, "Output name.", false),
	column("action", tString, "create, update, delete or no-op.", false),
	column("sensitive", tBool, "Whether the output is sensitive before or after the change.", false),
	column("unknown", tBool, "Whether the new value is known only after apply.", false),
	column("before", tJSON, "Value before the change; NULL when sensitive or new.", true),
	column("after", tJSON, "Value after the change; NULL when sensitive, unknown or deleted.", true),
}, nil)

func planOutputRows(b []byte) ([][]any, error) {
	p, err := parsePlan(b)
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(p.OutputChanges))
	for n := range p.OutputChanges {
		names = append(names, n)
	}
	sort.Strings(names)
	rows := make([][]any, 0, len(names))
	for _, n := range names {
		c := p.OutputChanges[n]
		sensitive := hasTrue(c.BeforeSensitive) || hasTrue(c.AfterSensitive)
		unknown := hasTrue(c.AfterUnknown)
		var before, after any
		if !sensitive {
			before = toJSON(c.Before)
			if !unknown {
				after = toJSON(c.After)
			}
		}
		rows = append(rows, []any{n, actionSummary(c.Actions), sensitive, unknown, before, after})
	}
	return rows, nil
}
